const CHALET_GRANDE_CERISE_DATA: PageDetail = {
  slug: "chalet-grande-cerise",
  logoImage: "/images/projects/chalet-grande-cerise/logo.png", logoAlt: "Chalet Grande Cerise logo",
  title: "Chalet Grande Cerise · Giovanni De Gattis",
  description: "Brand identity, web design and digital strategy for an exclusive alpine holiday home in Valle d'Aosta.",
  liveUrl: "https://chaletgrandecerise.it",
  liveFaviconUrl: "https://www.chaletgrandecerise.it/assets/logo-grande-cerise-BrDebEcr.png",
  figmaUrl: "",
  bodyHtml: `<div class="reading-meta"><time datetime="2025">2025</time><span>Private client</span></div><div data-reveal class="project-title-block"><h1 class="text-base font-display font-medium leading-snug"><span class="text-[var(--c-text)] dark:text-[var(--c-dark-text)]">Chalet Grande Cerise</span></h1><p class="text-base leading-[1.7] text-[var(--c-muted)] dark:text-[var(--c-dark-muted)]">Brand Identity, Web Design &amp; Digital Strategy · 2025</p></div><div data-reveal data-zoom aria-label="Open Chalet Grande Cerise project image fullscreen" class="project-poster rounded-[2rem] overflow-hidden" style="corner-shape: squircle"><div class="blur-img-wrap" style="aspect-ratio: 4 / 3"><picture><img src="/images/projects/chalet-grande-cerise/mockup-desktop-clean.jpg" alt="Chalet Grande Cerise project preview" loading="eager" decoding="async" class="blur-img" data-blur-main></picture></div></div><article data-reveal class="project-body"><h2 id="context">Context</h2>\n<p>Chalet Grande Cerise is an exclusive alpine holiday home located in Valle d'Aosta. The project aimed to create a warm, premium brand identity and an immersive digital presence that could convey the tranquility and authenticity of the mountain retreat.</p>\n<h2 id="the-approach">The Approach</h2>\n<p>I defined a distinct visual language tailored to the property's intimate atmosphere, pairing refined typography with natural textures and high-quality photography.</p>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/chalet-grande-cerise/mockup-desktop-clean.jpg" alt="Chalet Grande Cerise Desktop Web Experience" class="project-img" loading="lazy">\n</div>\n<h2 id="what-i-made">What I Made</h2>\n<p>I produced the complete visual identity, printed stationery and business cards, promotional social assets, and the responsive website. The site is crafted to guide visitors seamlessly through the property's amenities, rooms, and local activities.</p>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/chalet-grande-cerise/mockup-business-cards.webp" alt="Chalet Grande Cerise Printed Business Cards on Rustic Wood" class="project-img" loading="lazy">\n</div>\n<aside class="case-study"><div class="case-study-header"><span class="case-study-kicker">Digital focus</span><span class="case-study-title">Turning visits into action</span></div><p>One of the key website features was an integrated booking enquiry flow and promotional pop-up. By presenting targeted offers at the right moment in the user journey, it produced a sharp increase in direct guest inquiries.</p></aside>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/chalet-grande-cerise/mockup-popup-upselling.webp" alt="Chalet Grande Cerise Promotional Popup &amp; Upselling Flow" class="project-img" loading="lazy">\n</div>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n</div>\n<h2 id="reflection">Reflection</h2>\n<p>This project showed me that attracting visitors is only part of the work. What matters is turning that attention into action: a website needs to guide people towards a booking, an enquiry or a decision.</p></article><nav class="back-to-top-wrap" aria-label="Back to top"><a href="#" class="back-to-top" data-back-to-top><span class="back-to-top-label">Back to top</span></a></nav>`,
};

const VDA_CASE_VACANZE_DATA: PageDetail = {
  slug: "vda-case-vacanze",
  logoImage: "/images/projects/vda-case-vacanze/logo.png", logoAlt: "VDA Case Vacanze logo",
  title: "VDA Case Vacanze · Giovanni De Gattis",
  description: "Brand identity, graphic system and digital platform for a holiday property management network in Valle d'Aosta.",
  liveUrl: "",
  figmaUrl: "",
  bodyHtml: `<div class="reading-meta"><time datetime="2025">2025</time><span>Private client</span></div><div data-reveal class="project-title-block"><h1 class="text-base font-display font-medium leading-snug"><span class="text-[var(--c-text)] dark:text-[var(--c-dark-text)]">VDA Case Vacanze</span></h1><p class="text-base leading-[1.7] text-[var(--c-muted)] dark:text-[var(--c-dark-muted)]">Brand Identity, Graphic System &amp; Web Platform · 2025</p></div><div data-reveal data-zoom aria-label="Open VDA Case Vacanze project image fullscreen" class="project-poster rounded-[2rem] overflow-hidden" style="corner-shape: squircle"><div class="blur-img-wrap" style="aspect-ratio: 4 / 3"><picture><img src="/images/projects/vda-case-vacanze/thumb.webp" alt="VDA Case Vacanze project preview" loading="eager" decoding="async" class="blur-img" data-blur-main></picture></div></div><article data-reveal class="project-body"><h2 id="context">Context</h2>\n<p>VDA Case Vacanze is a hospitality and property management agency based in Valle d'Aosta. Unlike a single rental home, it operates as an umbrella agency managing a growing portfolio of vacation rentals across the region.</p>\n<h2 id="the-identity">The Identity System</h2>\n<p>The agency required a flexible, corporate-ready visual identity that communicated trustworthiness, alpine heritage, and structured organisation to both property owners and holiday travelers.</p>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/vda-case-vacanze/01_brand_identity.webp" alt="VDA Case Vacanze Brand Identity System" class="project-img" loading="lazy">\n</div>\n<h2 id="the-symbol">Symbol &amp; Geometry</h2>\n<p>The logomark combines mountain contours with architectural rooflines, producing a modern geometric mark that works cleanly across signage, keys, uniforms, and digital interfaces.</p>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/vda-case-vacanze/02_logo_symbol.webp" alt="VDA Case Vacanze Logo Mark" class="project-img" loading="lazy">\n</div>\n<h2 id="digital-platform">Digital Platform</h2>\n<p>I designed the digital agency platform to showcase multiple properties with intuitive search, regional filters, and clear booking inquiries.</p>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/vda-case-vacanze/03_website_mockup.webp" alt="VDA Case Vacanze Digital Platform" class="project-img" loading="lazy">\n</div>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/vda-case-vacanze/04_typography_pattern.webp" alt="VDA Case Vacanze Pattern & Typography" class="project-img" loading="lazy">\n</div>\n<h2 id="reflection">Reflection</h2>\n<p>Designing for an agency network taught me the value of building scalable brand guidelines that remain consistent as new properties, physical collateral, and marketing channels are added over time.</p></article><nav class="back-to-top-wrap" aria-label="Back to top"><a href="#" class="back-to-top" data-back-to-top><span class="back-to-top-label">Back to top</span></a></nav>`,
};

const POLITO_SAILING_TEAM_DATA: PageDetail = {
  slug: "polito-sailing-team",
  logoImage: "/images/projects/polito-sailing-team/logo.png", logoAlt: "PoliTO Sailing Team logo",
  title: "PoliTO Sailing Team · Giovanni De Gattis",
  description: "Brand identity and communication system for the PoliTO Sailing Team.",
  liveUrl: "",
  figmaUrl: "",
  actionLinks: [
    {
      label: "Instagram",
      href: "https://www.instagram.com/polito_sailing_team/",
      type: "site",
    },
  ],
  bodyHtml: `<div class="reading-meta"><time datetime="2023">2023-2024</time><span>Politecnico di Torino</span></div><div data-reveal class="project-title-block"><h1 class="text-base font-display font-medium leading-snug"><span class="text-[var(--c-text)] dark:text-[var(--c-dark-text)]">PoliTO Sailing Team</span></h1><p class="text-base leading-[1.7] text-[var(--c-muted)] dark:text-[var(--c-dark-muted)]">Brand Identity, Editorial Design &amp; Digital Communication · 2023-2024</p></div><div data-reveal data-zoom aria-label="Open PoliTO Sailing Team project image fullscreen" class="project-poster rounded-[2rem] overflow-hidden" style="corner-shape: squircle"><div class="blur-img-wrap" style="aspect-ratio: 4 / 3"><picture><img src="/images/projects/polito-sailing-team/thumb.webp" alt="PoliTO Sailing Team project preview" loading="eager" decoding="async" class="blur-img" data-blur-main></picture></div></div><article data-reveal class="project-body"><h2 id="context">Context</h2>\n<p>PoliTO Sailing Team is a real student team at Politecnico di Torino. The project was developed by a team of four designers, with the aim of strengthening how the team presented itself to partners, supporters and the public.</p>\n<h2 id="the-need">The Need</h2>\n<p>For a student team, visibility is not secondary: it is essential to securing funding, building partnerships and sustaining the work behind the boat. The communication system needed to feel credible, recognisable and appropriate for a professional context.</p>\n<h2 id="the-rebrand">The Rebrand</h2>\n<p>I worked on the rebranding of the logo and <a href="https://www.instagram.com/polito_sailing_team/" target="_blank" rel="noopener noreferrer" class="inline-link">social media presence</a>, helping shape a more coherent identity across the team’s communication. The visual language had to connect the technical world of sailing and engineering with a clearer public-facing image.</p>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/polito-sailing-team/01_branding_slide.webp" alt="PoliTO Sailing Team visual rebranding overview" class="project-img" loading="lazy">\n</div>\n<h2 id="what-we-made">What We Made</h2>\n<p>The project extended across the full communication system: website, business cards, stickers and merchandise, editorial materials, sponsor deck and social media content. All of these elements were used by the team.</p>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/polito-sailing-team/04_editorial_brochure.webp" alt="PoliTO Sailing Team Editorial Brochure &amp; Technical Specifications" class="project-img" loading="lazy">\n</div>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/polito-sailing-team/mockup-desktop-instagram.webp" alt="PoliTO Sailing Team Instagram profile on desktop monitor" class="project-img" loading="lazy">\n</div>\n<aside class="case-study"><div class="case-study-header"><span class="case-study-kicker">Public moment</span><span class="case-study-title">From screen to the team gala</span></div><p>One of the moments I am most proud of was designing a 3 × 2 metre display panel for a team gala evening. Seeing the identity move from screen and print into a physical event made the work feel tangible and real.</p></aside>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/polito-sailing-team/07_gala_evening.webp" alt="PoliTO Sailing Team 10 Years Gala Evening with Selene Boat on display" class="project-img" loading="lazy">\n</div>\n<div class="project-img-wrap" style="aspect-ratio: 4 / 3">\n  \n  <img src="/images/projects/polito-sailing-team/06_boat_render.webp" alt="PoliTO Sailing Team vessel 3D model and render" class="project-img" loading="lazy">\n</div>\n<h2 id="reflection">Reflection</h2>\n<p>This project taught me how to design for a context very different from the ones I was used to. I learned to balance visual expression with credibility, relationships and the expectations of a more formal, business-oriented audience.</p></article><nav class="back-to-top-wrap" aria-label="Back to top"><a href="#" class="back-to-top" data-back-to-top><span class="back-to-top-label">Back to top</span></a></nav>`,
};

